import { readdirSync, statSync } from "node:fs";
import { join, resolve } from "node:path";
import { defineConfig } from "vite-plus";

const root = import.meta.dirname;

// Generated by scripts/build-docs.mjs (runs in `prebuild`): one page per docs/**/*.md.
const walk = (d: string): string[] =>
  readdirSync(d).flatMap((f) => {
    const p = join(d, f);
    return statSync(p).isDirectory() ? walk(p) : p.endsWith(".html") ? [p] : [];
  });
let docPages: string[] = [];
try {
  docPages = walk(join(root, "docs"));
} catch {
  // docs/ not generated yet (dev server before the first build)
}

export default defineConfig({
  build: {
    rollupOptions: {
      input: {
        main: resolve(root, "index.html"),
        claude: resolve(root, "claude-code.html"),
        examples: resolve(root, "examples.html"),
        docs: resolve(root, "docs.html"),
        ...Object.fromEntries(docPages.map((p) => [`doc/${p.slice(join(root, "docs").length + 1).replace(/[\/]index\.html$/, "")}`, p])),
      },
    },
  },
});
